11	// readBrainManifestFile decodes the canonical manifest without a byte ceiling.
12	// It uses the same checked descriptor as bounded state readers, without needing
13	// the source repository or Git. encoding/json buffers a whole JSON value and
14	// the manifest is materialized in memory: this is NOT a bounded-memory reader.
15	// Rewinding this descriptor (never reopening the path) preserves schema-first
16	// checks and tolerant reads versus strict rewrites, including unknown fields.
17	func readBrainManifestFile(brainDir string, tolerateUnknown bool) (*exportManifest, int, bool, bool, error) {
18		f, present, err := openMemoryStateFileExpected(brainDir, exportManifestFileName, "brain manifest", nil)
19		if err != nil {
20			return nil, 0, false, present, fmt.Errorf("read brain manifest: %w", err)
21		}
22		if !present {
23			return &exportManifest{SchemaVersion: brainManifestSchemaVersion}, 0, false, false, nil
24		}
25		defer f.Close()
26		manifest, version, dropped, err := decodeBrainManifestFile(f, tolerateUnknown)
27		return manifest, version, dropped, true, err
28	}
29	
30	func decodeManifestPass(f *os.File, out any, strict bool) error {
31		if _, err := f.Seek(0, io.SeekStart); err != nil {
32			return err
33		}
34		decoder := json.NewDecoder(f)
35		if strict {
36			decoder.DisallowUnknownFields()
37		}
38		if err := decoder.Decode(out); err != nil {
39			return err
40		}
41		if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
42			return errTrailingJSONData
43		}
44		return nil
45	}
46	
47	func decodeBrainManifestFile(f *os.File, tolerateUnknown bool) (*exportManifest, int, bool, error) {
48		var header struct {
49			SchemaVersion int `json:"schema_version"`
50		}
51		if err := decodeManifestPass(f, &header, false); err != nil {
52			return nil, 0, false, fmt.Errorf("parse brain manifest: %s: brain manifest cannot be parsed: %w", memoryErrStateCorrupt, err)
53		}
54		version := header.SchemaVersion
55		if version > brainManifestSchemaVersion {
56			return nil, version, false, fmt.Errorf("%s: brain manifest schema version %d is newer than supported version %d", memoryErrUnsupportedVersion, version, brainManifestSchemaVersion)
57		}
58		var manifest exportManifest
59		err := decodeManifestPass(f, &manifest, true)
60		dropped := false
61		if tolerateUnknown && isUnknownFieldError(err) {
62			manifest = exportManifest{}
63			err = decodeManifestPass(f, &manifest, false)
64			dropped = err == nil
65		}

